import { useState, type FormEvent } from 'react'
import { Link, useNavigate, useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Button } from '../components/Button'
import { Card } from '../components/Card'
import { Input } from '../components/Input'
import { LanguageSwitcher } from '../components/LanguageSwitcher'
import { useAuth } from '../auth/AuthContext'
import { roleLabelKey } from '../services/authService'
import type { UserRole } from '../types/auth'

const roles: UserRole[] = ['traveler', 'operator', 'vendor', 'coordinator']
export function RegisterPage() {
  const { register, loading } = useAuth(); const navigate = useNavigate(); const [searchParams] = useSearchParams()
  const { t } = useTranslation()
  const [form, setForm] = useState({ name: '', email: '', phone: '', password: '', confirmPassword: '', role: 'traveler' as UserRole, terms: false, referredBy: searchParams.get('ref') || '' })
  const [error, setError] = useState('')
  const update = <K extends keyof typeof form>(key: K, value: typeof form[K]) => setForm((current) => ({ ...current, [key]: value }))
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); if (!form.name || !form.email || !form.phone || !form.password || !form.confirmPassword) return setError(t('register.completeAllFields')); if (!/^\S+@\S+\.\S+$/.test(form.email)) return setError(t('register.validEmail')); if (form.password.length < 8) return setError(t('register.passwordLength')); if (form.password !== form.confirmPassword) return setError(t('register.passwordsMismatch')); if (!form.terms) return setError(t('register.acceptTerms')); try { const user = await register({ name: form.name, email: form.email, phone: form.phone, password: form.password, role: form.role, referredBy: form.referredBy.trim() || undefined }); navigate(user.role === 'traveler' ? '/traveler/onboarding' : user.role === 'operator' ? '/operator' : user.role === 'coordinator' ? '/coordinator/schedule' : '/vendor', { replace: true }) } catch (reason) { setError(reason instanceof Error ? reason.message : t('register.unableToCreate')) } }
  return <section className="auth-page"><div className="auth-brand"><Link to="/login">Voyara<span>✦</span></Link><p>{t('register.tagline')}</p><LanguageSwitcher /></div><Card className="auth-card"><p className="eyebrow">{t('register.eyebrow')}</p><h1>{t('register.title')}</h1><p className="auth-copy">{t('register.copy')}</p><form onSubmit={submit}><Input label={t('register.fullName')} onChange={(event) => update('name', event.target.value)} placeholder={t('register.fullNamePlaceholder')} value={form.name} /><Input label={t('register.email')} onChange={(event) => update('email', event.target.value)} placeholder="you@example.com" type="email" value={form.email} /><Input label={t('register.phone')} onChange={(event) => update('phone', event.target.value)} placeholder="+91 98765 43210" type="tel" value={form.phone} /><div className="auth-role-selector">{roles.map((item) => <button className={form.role === item ? 'is-active' : ''} key={item} onClick={() => update('role', item)} type="button">{t(roleLabelKey(item))}</button>)}</div><Input label={t('register.password')} onChange={(event) => update('password', event.target.value)} placeholder={t('register.minChars')} type="password" value={form.password} /><Input label={t('register.confirmPassword')} onChange={(event) => update('confirmPassword', event.target.value)} type="password" value={form.confirmPassword} /><Input hint={t('register.referralHint')} label={t('register.referralCode')} onChange={(event) => update('referredBy', event.target.value)} placeholder="e.g. a1b2c3d4e5f6" value={form.referredBy} /><label className="auth-terms"><input checked={form.terms} onChange={(event) => update('terms', event.target.checked)} type="checkbox" /> {t('register.acceptTermsLabel')}</label>{error && <p className="auth-error" role="alert">{error}</p>}<Button disabled={loading} type="submit">{loading ? t('register.creatingAccount') : t('register.createAccountButton')}</Button></form><p className="auth-footer">{t('register.alreadyMember')} <Link to="/login">{t('register.logIn')}</Link></p></Card></section>
}
